# generated by gophertunnel b8bd735:
# packet.ResourcePackStack{IncludeEditorPacks: true}
EDITOR_ONLY = bytes.fromhex("000000000000000001")

# generated by gophertunnel b8bd735:
# packet.ResourcePackStack{TexturePacks: make([]protocol.StackResourcePack, 300)}, each UUID set to
# "00000000-0000-0000-0000-000000000000"
THREE_HUNDRED_PACKS = (
    bytes.fromhex("00ac02")
    + bytes.fromhex("2430303030303030302d303030302d303030302d303030302d3030303030303030303030300000") * 300
    + bytes.fromhex("00000000000000")
)

GOLDENS = [
    pytest.param(
        v2225.ResourcePackStackPacket(
            texture_pack_required=True,
            texture_pack_ids_and_versions=[
                v2225.PackInstanceId(
                    pack_id=uuid.UUID("5a1c2b3d-4e5f-4a6b-8c7d-9e0f1a2b3c4d"), version="1.2.3", subpack_name="hd"
                ),
                v2225.PackInstanceId(pack_id=uuid.UUID("6b2d3c4e-5f60-4b7c-9d8e-0f1a2b3c4d5e"), version="0.0.1"),
            ],
            base_game_version="1.26.44",
            experiments=v2225.Experiments(
                toggles=[
                    v2225.ExperimentToggle(name="gametest", enabled=True),
                    v2225.ExperimentToggle(name="data_driven_biomes", enabled=False),
                ],
                experiments_ever_toggled=True,
            ),
            include_editor_packs=True,
        ),
        STACK,
        id="full",
    ),
    pytest.param(v2225.ResourcePackStackPacket(include_editor_packs=True), EDITOR_ONLY, id="editor-only"),
    pytest.param(
        v2225.ResourcePackStackPacket(texture_pack_ids_and_versions=[v2225.PackInstanceId()] * 300),
        THREE_HUNDRED_PACKS,
        id="300-packs",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_resource_pack_stack_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_resource_pack_stack_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
